const tasks = $input.all().map(item => item.json);

const totalTasks = tasks.length;

const urgentTasks = tasks.filter(
  task => task.urgency === "Urgent" || task.urgency === "Overdue"
).length;

const highUrgencyTasks = tasks.filter(
  task => task.urgency === "High"
).length;

const highPriorityTasks = tasks.filter(
  task => task.priority === "High"
).length;

const deadlinesWithin3Days = tasks.filter(
  task => Number(task.days_remaining) <= 3
).length;

let workloadLevel;

if (totalTasks === 0) {
  workloadLevel = "None";
} else if (
  urgentTasks > 0 ||
  deadlinesWithin3Days >= 2 ||
  totalTasks >= 6
) {
  workloadLevel = "High";
} else if (
  highUrgencyTasks > 0 ||
  highPriorityTasks >= 2 ||
  totalTasks >= 3
) {
  workloadLevel = "Medium";
} else {
  workloadLevel = "Low";
}

return [
  {
    json: {
      totalTasks,
      urgentTasks,
      highUrgencyTasks,
      highPriorityTasks,
      deadlinesWithin3Days,
      workloadLevel,
      tasks
    }
  }
];

const data = $input.first().json;

const tasks = [...data.tasks];

const conflicts = [];

for (let i = 0; i < tasks.length; i++) {
  for (let j = i + 1; j < tasks.length; j++) {

    const taskA = tasks[i];
    const taskB = tasks[j];

    const daysA = Number(taskA.days_remaining);
    const daysB = Number(taskB.days_remaining);

    const difference = Math.abs(daysA - daysB);

    if (difference <= 1) {
      conflicts.push({
        task1: taskA.task,
        subject1: taskA.subject,
        deadline1: taskA.deadline,

        task2: taskB.task,
        subject2: taskB.subject,
        deadline2: taskB.deadline,

        daysDifference: difference
      });
    }
  }
}

return [
  {
    json: {
      ...data,
      deadlineConflicts: conflicts,
      conflictCount: conflicts.length
    }
  }
];

const data = $input.first().json;

const recommended = data.recommendedTask;

const summary = {
  totalPendingTasks: data.totalTasks,
  workloadLevel: data.workloadLevel,
  highUrgencyTasks: data.highUrgencyTasks,
  highPriorityTasks: data.highPriorityTasks,
  deadlinesWithin3Days: data.deadlinesWithin3Days,
  deadlineConflicts: data.conflictCount,

  recommendedTask: {
    subject: recommended.subject,
    task: recommended.task,
    deadline: recommended.deadline,
    daysRemaining: recommended.days_remaining,
    priority: recommended.priority,
    urgency: recommended.urgency,
    recommendationScore: recommended.recommendationScore
  }
};

return [
  {
    json: {
      ...data,
      dailySummary: summary
    }
  }
];

const data = $input.first().json;

const tasks = [...data.tasks];

const urgencyWeight = {
  "Overdue": 1,
  "Urgent": 2,
  "High": 3,
  "Medium": 4,
  "Low": 5
};

const priorityWeight = {
  "High": 1,
  "Medium": 2,
  "Low": 3
};

// Calculate a score for every task
const scoredTasks = tasks.map(task => {
  const urgencyScore = urgencyWeight[task.urgency] ?? 99;
  const priorityScore = priorityWeight[task.priority] ?? 99;
  const daysRemaining = Number(task.days_remaining);

  let score = 0;

  // More urgent = higher score
  score += (6 - urgencyScore) * 10;

  // Less time remaining = higher score
  if (daysRemaining <= 1) {
    score += 30;
  } else if (daysRemaining <= 3) {
    score += 20;
  } else if (daysRemaining <= 7) {
    score += 10;
  }

  // Higher priority = higher score
  score += (4 - priorityScore) * 5;

  // Deadline conflict gets additional importance
  const hasConflict = data.deadlineConflicts.some(conflict =>
    conflict.task1 === task.task ||
    conflict.task2 === task.task
  );

  if (hasConflict) {
    score += 15;
  }

  return {
    ...task,
    recommendationScore: score,
    hasDeadlineConflict: hasConflict
  };
});

// Highest score first
scoredTasks.sort(
  (a, b) => b.recommendationScore - a.recommendationScore
);

const recommendedTask = scoredTasks[0];

return [
  {
    json: {
      ...data,
      recommendedTask,
      rankedTasks: scoredTasks
    }
  }
];

